/* Your Day: no network, analytics, external fonts or runtime dependencies. */
(()=>{'use strict';
 const C=window.Jai,KEY='jai-daily.v1',$=s=>document.querySelector(s);
 const paths={menu:'M4 6h16M4 12h16M4 18h16',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',water:'M12 3C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-12Z M9 16a3 3 0 0 0 3 3',schedule:'M5 5h14v16H5zM8 3v4M16 3v4M5 10h14M8 14h3M8 17h6',workout:'M3 9v6M6 6v12M6 12h12M18 6v12M21 9v6',meals:'M6 3v7M3 3v4a3 3 0 0 0 6 0V3M6 10v11M17 3c-4 2-4 9 0 9h2M19 3v18',care:'M20 5a5 5 0 0 0-8-1 5 5 0 0 0-8 6l8 10 8-10a5 5 0 0 0 0-5Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM10 3h4l1 3 3 1 3 2v4l-3 2-1 3-3 3h-4l-2-3-3-1-2-3v-4l3-2 1-3Z',check:'M5 12l4 4L19 6',plus:'M12 5v14M5 12h14',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15Z',arrow:'M5 12h14m-5-5 5 5-5 5',info:'M12 11v6M12 7v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',leaf:'M20 3C8 1 2 8 5 15c3 7 15 3 15-12ZM4 21l12-13',clock:'M12 7v5l4 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',pet:'M8 11C2-1 8-1 10 9M14 9c2-10 8-10 6 2M6 16a6 6 0 0 1 12 0c0 7-12 7-12 0ZM9 15v.1M15 15v.1M11 18h2',close:'m6 6 12 12M6 18 18 6'};
 const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.leaf}"/></svg>`;
 const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const n=x=>Number(x).toLocaleString('th-TH',{maximumFractionDigits:1});
 const litres=ml=>(ml/1000).toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:2});
 const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const shift=(date,delta)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+delta);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 const thaiDate=date=>new Date(date+'T12:00:00').toLocaleDateString('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 const routes={dashboard:['ภาพรวม','วันของคุณ','ภาพเล็ก ๆ ของการดูแลตัวเองในแต่ละวัน'],water:['ดื่มน้ำ','เติมความสดชื่น','บันทึกทีละแก้ว ดูยอดเปลี่ยนทันที'],schedule:['ตารางชีวิตรายวัน','จัดวันให้เป็นจังหวะ','วางแผน ปรับเปลี่ยน และเริ่มใหม่ได้เสมอ'],workout:['ออกกำลังกาย','ขยับร่างกาย ใจสบาย','แผนที่ยืดหยุ่นได้ตามความพร้อมของคุณ'],meals:['อาหาร / สารอาหาร','ทุกมื้อของวันนี้','บันทึกเพื่อรู้จักตัวเอง โดยไม่มีโควตาแคลอรี'],care:['ดูแลตัวเองและกระแต','ดูแลกันในทุกวัน','พื้นที่เล็ก ๆ ของคุณและเจ้ากระแต'],settings:['ตั้งค่า','พื้นที่ในแบบของคุณ','จัดการค่าพื้นฐานและสำรองข้อมูล']};
 let storageBlocked=false,rawBackup=null,state,storageIssue='';
 try{rawBackup=localStorage.getItem(KEY);state=rawBackup===null?C.createState():C.parseImport(rawBackup);}catch(err){state=C.createState();storageBlocked=true;storageIssue=rawBackup!==null?'อ่านข้อมูลเดิมไม่ได้ ข้อมูลเดิมยังไม่ถูกเขียนทับ กรุณาดาวน์โหลดสำรองก่อนเริ่มใหม่':'เบราว์เซอร์ไม่อนุญาตให้บันทึก ขณะนี้ข้อมูลอยู่ชั่วคราว ควรส่งออก JSON ก่อนปิดหน้า';}
 let date=localDate(),page=Object.hasOwn(routes,location.hash.slice(1))?location.hash.slice(1):'dashboard',editor=null,toastTimer,deleteArmed=false;
 const d=()=>C.day(state,date),stats=()=>C.waterStats(state,date);
 function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
 function save(message){
  if(!storageBlocked){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveState').textContent='บันทึกแล้วในเครื่อง';}catch(err){storageBlocked=true;storageIssue='บันทึกไม่สำเร็จ พื้นที่อาจเต็มหรือเบราว์เซอร์จำกัดการบันทึก ส่งออก JSON เพื่อเก็บข้อมูลก่อนปิดหน้า';}}
  if(storageBlocked){$('#saveState').textContent='ยังไม่ได้บันทึกถาวร';if(message)toast('ยังบันทึกในเครื่องไม่ได้ · ส่งออก JSON เพื่อสำรอง');}else if(message)toast(message);
 }
 const btn=(text,action,style='soft',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
 const notice=(text,kind='')=>`<div class="notice ${kind}">${icon('info')}<div>${text}</div></div>`;
 function ring(w){const ref=state.settings.waterReference,percent=ref?Math.min(100,w.ml/ref*100):0;return `<div class="ring" role="img" aria-label="ดื่มแล้ว ${litres(w.ml)} ลิตร${ref?' เทียบแผนอ้างอิง '+litres(ref)+' ลิตร':''}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="track" cx="60" cy="60" r="51"/><circle class="fill" cx="60" cy="60" r="51" stroke-dasharray="${percent*3.2044} 320.44"/></svg><div class="ring-number"><strong>${litres(w.ml)}</strong><span>ลิตรที่ดื่มแล้ว</span></div></div>`;}
 function waterSummary(){const w=stats();return `<div class="water-summary">${ring(w)}<div class="water-detail"><h3>${n(w.count)} แก้วแล้ววันนี้</h3><p>จากรายการ ${d().waterPlan.length} แก้ว<br>ปริมาณตามรายการ ${litres(w.planned)} ลิตร</p><span class="badge">${state.settings.waterReference?'อ้างอิง '+litres(state.settings.waterReference)+' ลิตร':'ปิดค่าอ้างอิงแล้ว'}</span></div></div>`;}
 const empty=(title,text,action,label)=>`<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p>${action?btn(label,action,'primary'):''}</div>`;
 function miniWater(){return `<div class="mini-slots">${d().waterPlan.map(x=>`<button class="mini-slot" data-action="water-toggle" data-id="${e(x.id)}" aria-pressed="${d().water.includes(x.id)}" aria-label="น้ำ ${x.time} ${x.ml} มิลลิลิตร">${d().water.includes(x.id)?icon('check'):icon('water')}${e(x.time)}</button>`).join('')}</div>`;}
 function weekChart(){const dow=new Date(date+'T12:00:00').getDay(),start=shift(date,-((dow+6)%7));const data=Array.from({length:7},(_,i)=>{const t=shift(start,i);const day=state.days[t];return {t,ml:day?day.waterPlan.filter(x=>day.water.includes(x.id)).reduce((a,x)=>a+x.ml,0):0};});const max=Math.max(3300,...data.map(x=>x.ml));return `<div class="week-chart" aria-label="น้ำที่บันทึกใน 7 วัน">${data.map((x,i)=>`<button class="chart-col ${x.t===date?'current':''}" data-action="select-date" data-date="${x.t}" aria-label="${thaiDate(x.t)} ${litres(x.ml)} ลิตร"><small>${litres(x.ml)}</small><div class="bar-track"><span class="bar" style="height:${x.ml/max*100}%"></span></div><span class="chart-label day-label">${['จ.','อ.','พ.','พฤ.','ศ.','ส.','อา.'][i]}</span></button>`).join('')}</div>`;}
 function dashboard(){
  const w=stats(),day=d(),done=day.schedule.filter(x=>x.status==='done').length,t=C.nutrition(day.meals),work=C.workoutFor(state,date),workCount=work.exercises.filter(x=>day.workoutDone.includes(work.group+'-'+x.id)).length;
  const art=`<svg class="welcome-art" aria-hidden="true" viewBox="0 0 180 160"><circle cx="100" cy="78" r="67" fill="#ccebf6"/><path d="M72 151C55 114 74 64 121 22c8 46-8 83-49 129Z" fill="#49a2c1"/><path d="M71 151C87 106 64 71 29 64c-7 39 6 67 42 87Z" fill="#8cd1e1"/><path d="M73 151 115 37M72 151 38 76" fill="none" stroke="#e8f8fd" stroke-width="2"/><path d="M132 100h13m-6-6v12M35 35h10m-5-5v10" stroke="#3187a7" stroke-width="2"/></svg>`;
  return `<section class="welcome"><div><p class="eyebrow">A LITTLE CARE, EVERY DAY</p><h2>ค่อย ๆ ดูแลตัวเอง<br>ในจังหวะของ${e(state.settings.name)}</h2><p>ไม่ต้องทำทุกอย่างให้ครบ แค่ได้กลับมาดูแลตัวเองก็เป็นการเริ่มต้นที่ดี</p><span class="badge">${icon('leaf')} ${thaiDate(date)}</span></div>${art}</section>
   <div class="stats">
    <article class="card stat"><div class="stat-top"><span>น้ำที่ดื่มแล้ว</span><i class="icon-tile">${icon('water')}</i></div><div class="stat-value">${litres(w.ml)}<small>ลิตร</small></div><p class="stat-desc">${w.count} แก้ว · ติ๊กแล้วรวมให้ทันที</p></article>
    <article class="card stat"><div class="stat-top"><span>ตารางชีวิต</span><i class="icon-tile purple">${icon('schedule')}</i></div><div class="stat-value">${done}<small>/ ${day.schedule.length} รายการ</small></div><p class="stat-desc">ทำแล้ว · ปรับสถานะได้เสมอ</p></article>
    <article class="card stat"><div class="stat-top"><span>การเคลื่อนไหว</span><i class="icon-tile blue">${icon('workout')}</i></div><div class="stat-value">${workCount}<small>/ ${work.exercises.length} ท่า</small></div><p class="stat-desc">${e(work.group==='rest'?'วันพัก':work.group==='active'?'Active recovery':'แผนกลุ่ม '+work.group)}</p></article>
    <article class="card stat"><div class="stat-top"><span>อาหารที่บันทึก</span><i class="icon-tile orange">${icon('meals')}</i></div><div class="stat-value">${n(t.kcal.value)}<small>kcal${t.kcal.missing?' *':''}</small></div><p class="stat-desc">ประมาณการจาก ${day.meals.length} รายการ</p></article>
   </div>
   <div class="dashboard-grid"><div class="stack"><section class="card water-card"><div class="card-header"><div><h2>เติมน้ำให้วันของคุณ</h2><p>แก้วเล็ก ๆ ที่บันทึกได้ทันที</p></div><span class="badge">WATER</span></div>${waterSummary()}${miniWater()}<div class="card-foot">แผนอ้างอิงไม่ใช่เป้าหมายบังคับ · ปรับตามความต้องการของคุณ</div><button class="text-btn" data-page="water">ดูบันทึกน้ำทั้งหมด ${icon('arrow')}</button></section><section class="card"><div class="card-header"><h2>น้ำที่บันทึกในสัปดาห์นี้</h2><span class="small muted">ลิตร / วัน</span></div>${weekChart()}<p class="small muted" style="margin-top:15px">กดแต่ละวันเพื่อดูข้อมูล · วันที่ยังไม่บันทึกแสดง 0</p></section></div>
   <div class="stack"><section class="card"><div class="card-header"><div><h2>จังหวะของวันนี้</h2><p>${done} ทำแล้ว · ${day.schedule.filter(x=>x.status==='pending').length} ยังไม่ทำ · ${day.schedule.filter(x=>x.status==='unable').length} ทำไม่ได้ · ${day.schedule.filter(x=>x.status==='unknown').length} ไม่ทราบ</p></div><button class="text-btn" data-page="schedule">ดูทั้งหมด ${icon('arrow')}</button></div>${day.schedule.length?`<div class="timeline">${day.schedule.filter(x=>x.status!=='done').slice(0,5).concat(day.schedule.filter(x=>x.status==='done').slice(0,Math.max(0,5-day.schedule.filter(x=>x.status!=='done').length))).map(x=>`<div class="timeline-row"><span class="time">${e(x.time||'ไม่ระบุ')}</span><span class="timeline-dot ${x.status==='done'?'done':''}"></span><div><p class="timeline-title">${e(x.title)}</p><span class="timeline-note">${e(x.note)}</span></div><button class="icon-btn" data-action="schedule-edit" data-id="${e(x.id)}" aria-label="แก้ไข ${e(x.title)}">${icon('edit')}</button></div>`).join('')}</div>`:empty('วันนี้ยังเป็นหน้าว่าง','เพิ่มตารางในแบบของคุณ','schedule-add','เพิ่มกิจกรรม')}</section>
   <section class="card"><div class="card-header"><div><h2>ดูแลตัวเองและกระแต</h2><p>เรื่องเล็ก ๆ ที่อยากใส่ใจ</p></div><span class="icon-tile">${icon('pet')}</span></div>${state.care.filter(x=>x.category==='pet').slice(0,3).map(x=>careRow(x,false)).join('')}<button class="text-btn" data-page="care">ไปที่พื้นที่ดูแล ${icon('arrow')}</button></section></div></div>`;
 }
 function waterPage(){const w=stats();return `<div class="water-page-top"><section class="card water-card">${waterSummary()}</section><section class="card"><p class="eyebrow">TODAY'S WATER</p><h2>จิบเมื่อพร้อม บันทึกเมื่อดื่ม</h2><p class="small">ติ๊กเพื่อรวมปริมาณ ยกเลิกติ๊กได้ทุกเวลา<br>รายการและยอดบันทึกแยกเฉพาะ ${thaiDate(date)}</p><div class="progress" role="progressbar" aria-label="เทียบค่าอ้างอิงน้ำ" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.settings.waterReference?Math.min(100,Math.round(w.ml/state.settings.waterReference*100)):0}"><span style="width:${state.settings.waterReference?Math.min(100,w.ml/state.settings.waterReference*100):0}%"></span></div><p class="small muted" style="margin-top:10px">${state.settings.waterReference?'เทียบค่าอ้างอิง '+litres(state.settings.waterReference)+' ลิตร · ไม่จำเป็นต้องดื่มให้ครบ':'ไม่ได้ตั้งค่าอ้างอิง · แสดงเฉพาะปริมาณที่ดื่มจริง'}</p></section></div><div class="section-actions"><div><h2>เวลาของแต่ละแก้ว</h2><p>เริ่มต้น 11 เวลา × 300 มล. · แก้เฉพาะวันที่เลือก</p></div><div class="actions">${btn(icon('plus')+' เพิ่มแก้ว','water-add','primary')}${btn('ใช้แผนนี้เป็นค่าเริ่มต้น','water-default')}</div></div>${d().waterPlan.length?`<div class="slot-grid">${d().waterPlan.map(x=>`<div class="slot ${d().water.includes(x.id)?'checked':''}"><button class="slot-toggle" data-action="water-toggle" data-id="${e(x.id)}" aria-pressed="${d().water.includes(x.id)}" aria-label="น้ำ ${e(x.time)} ${n(x.ml)} มิลลิลิตร">${icon(d().water.includes(x.id)?'check':'water')}<strong>${e(x.time)}</strong><small>${n(x.ml)} มล. · ${d().water.includes(x.id)?'ดื่มแล้ว':'ยังไม่บันทึก'}</small></button><button class="slot-edit" data-action="water-edit" data-id="${e(x.id)}">แก้ไข ${e(x.time)}</button></div>`).join('')}</div>`:empty('ยังไม่มีรายการน้ำ','เพิ่มแก้วแรกเพื่อเริ่มบันทึก','water-add','เพิ่มแก้ว')}${notice('ยอดเป็นผลรวมของรายการที่ติ๊กจริง จำนวนแก้วอาจมีปริมาตรต่างกัน เปลี่ยนค่าอ้างอิงหรือปิดได้ที่หน้าตั้งค่า')}`;}
 function schedulePage(){return `<div class="section-actions"><p>${thaiDate(date)} · ${d().schedule.length} กิจกรรม</p><div class="actions">${btn('คัดลอกจากวันที่อื่น','schedule-copy')}${btn(icon('plus')+' เพิ่มกิจกรรม','schedule-add','primary')}</div></div>${date==='2026-10-19'?notice('ข้อมูลเริ่มต้นจากบทสนทนา: ยืนยันมื้อเช้าและกลางวันแล้ว · นอน 04:00–12:00 เป็นเป้าหมายที่ยังไม่ยืนยัน · กิจกรรมอื่นเป็นแผน ปรับสถานะตามสิ่งที่เกิดขึ้นจริง'):''}${d().schedule.length?`<div class="list">${d().schedule.map(x=>`<article class="card schedule-item ${x.status==='done'?'is-done':''}"><span class="time">${e(x.time||'ไม่ระบุ')}</span><div><h3 class="row-title">${e(x.title)}</h3><p class="row-note">${e(x.note)}</p></div><select class="status-select status-${x.status}" aria-label="สถานะ ${e(x.title)}" data-status-id="${e(x.id)}">${statusOptions(x.status)}</select><button class="icon-btn edit-schedule" data-action="schedule-edit" data-id="${e(x.id)}" aria-label="แก้ไข ${e(x.title)}">${icon('edit')}</button></article>`).join('')}</div>`:empty('วางวันของคุณเองได้เลย','วันอื่นไม่ได้ใส่ตารางสำเร็จรูปให้ คุณเพิ่มเองหรือคัดลอกแผนจากวันอื่นได้','schedule-add','เพิ่มกิจกรรมแรก')}`;}
 function mealsPage(){const t=C.nutrition(d().meals),fields=[['kcal','พลังงาน','kcal'],['protein','โปรตีน','กรัม'],['carbs','คาร์โบไฮเดรต','กรัม'],['fat','ไขมัน','กรัม']];return `${notice('<strong>ประมาณการจากข้อมูลที่กรอก</strong> · ไม่มีโควตาแคลอรี ช่องว่างหมายถึงไม่ทราบ ไม่ใช่ศูนย์ และยังไม่รวมในยอด')}
  <div class="meal-totals">${fields.map(([k,label,unit])=>`<article class="card nutrition-card"><span>${label}</span><strong>${n(t[k].value)}<small> ${unit}</small></strong><small>${t[k].missing?'ยังไม่รวม '+t[k].missing+' รายการที่ไม่ทราบค่า':'รวมจากรายการที่กรอก'}</small></article>`).join('')}</div><p class="small muted" style="margin-bottom:20px">ใยอาหาร ${n(t.fiber.value)} กรัม (${t.fiber.missing} รายการไม่ทราบ) · โซเดียม ${n(t.sodium.value)} มก. (${t.sodium.missing} รายการไม่ทราบ)</p>
  <div class="section-actions"><div><h2>มื้อที่บันทึก</h2><p>เพิ่ม แก้ไข และลบได้ตามที่กินจริง</p></div>${btn(icon('plus')+' เพิ่มอาหาร','meal-add','primary')}</div>${d().meals.length?`<div class="list">${d().meals.map(x=>`<article class="card meal-item"><div class="meal-icon">${icon('meals')}</div><div class="meal-body"><div class="meal-top"><span class="badge orange">${e(x.meal)}</span><span class="badge ${x.estimated?'muted':''}">${x.estimated?'ค่าประมาณ':'ข้อมูลที่กรอก / ฉลาก'}</span></div><h3>${e(x.name)}</h3><p>${e(x.note)}</p><div class="macros">${[['protein','โปรตีน','g'],['carbs','คาร์บ','g'],['fat','ไขมัน','g'],['fiber','ใยอาหาร','g'],['sodium','โซเดียม','mg']].map(([k,l,u])=>`<span>${l} <b>${x[k]===null?'ไม่ทราบ':n(x[k])+' '+u}</b></span>`).join('')}</div></div><div class="meal-kcal">${x.kcal===null?'ไม่ทราบ':n(x.kcal)}<small>kcal</small></div><button class="icon-btn" data-action="meal-edit" data-id="${e(x.id)}" aria-label="แก้ไข ${e(x.name)}">${icon('edit')}</button></article>`).join('')}</div>`:empty('บันทึกมื้อแรกของวันนี้','ใส่เฉพาะค่าที่ทราบ ส่วนที่ไม่ทราบเว้นว่างได้','meal-add','เพิ่มอาหาร')}`;}
 function workoutPage(){const w=C.workoutFor(state,date),dow=new Date(date+'T12:00:00').getDay(),start=shift(date,-((dow+6)%7)),totalSets=w.exercises.reduce((a,x)=>a+x.sets,0),phaseTotal=state.phases.reduce((a,x)=>a+x.minutes,0);return `<div class="week-pills">${Array.from({length:7},(_,i)=>{const t=shift(start,i),group=state.week[new Date(t+'T12:00:00').getDay()];return `<button class="day-pill ${t===date?'selected':''}" data-action="select-date" data-date="${t}" aria-label="${thaiDate(t)} กลุ่ม ${group}">${['จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์','อาทิตย์'][i]}<strong>${group==='rest'?'พัก':group==='active'?'เบา ๆ':'กลุ่ม '+group}</strong></button>`;}).join('')}</div><section class="card workout-intro"><div><span class="badge purple">${w.group==='rest'?'RECOVERY':w.group==='active'?'ACTIVE RECOVERY':'16:30–18:00 · แผนเวลา'}</span><h2>${e(w.title)}</h2><p>${w.group==='rest'?'พักและกลับมาดูแลความพร้อมของร่างกาย':w.group==='active'?'เลือกกิจกรรมสบาย ๆ ที่คุณอยากทำ':'ตัวอย่างท่าสำหรับแผนที่ระบุ · แก้ไขให้เหมาะกับคุณได้'}</p></div>${btn('แก้แผนประจำวันในสัปดาห์','workout-plan')}</section>
  ${['A','B'].includes(w.group)?`${notice('<strong>'+totalSets+' เซตในช่วงเวท '+(state.phases.find(x=>x.id==='p1')?.minutes??50)+' นาทีอาจไม่พอ</strong> โดยเฉพาะแผนเริ่มต้น 27 เซต / 50 นาที ควรลดท่าหรือปรับเวลาเมื่อจำเป็น ไม่จำเป็นต้องทำครบทั้งหมด','warning')}<div class="section-actions"><h2>แบ่งเวลา · ${phaseTotal} นาที</h2>${btn('แก้ไขช่วงเวลา','phase-edit')}</div><div class="phases">${state.phases.map(x=>`<div class="phase"><div><span>${e(x.name)}</span><strong>${n(x.minutes)}</strong><span>นาที</span></div>${icon('clock')}</div>`).join('')}</div>`:''}
  <div class="section-actions"><div><h2>${w.group==='rest'?'บันทึกวันพัก':'รายการที่วางไว้'}</h2><p>แก้รายการมีผลกับกลุ่มนี้ทุกสัปดาห์ · การทำแล้วแยกตามวันที่</p></div>${w.group!=='rest'?btn(icon('plus')+' เพิ่มรายการ','exercise-add','primary'):''}</div>
  ${w.group==='rest'?`<section class="card"><div class="care-row"><button class="check-btn" data-action="workout-toggle" data-id="rest" aria-pressed="${d().workoutDone.includes('rest')}" aria-label="บันทึกวันพัก">${icon('check')}</button><div class="row-text"><h3>พักตามที่วางไว้</h3><p class="row-note">กดเมื่ออยากบันทึกว่าได้พักแล้ววันนี้</p></div></div></section>`:w.exercises.length?`<section class="card">${w.exercises.map(x=>{const done=d().workoutDone.includes(w.group+'-'+x.id);return `<div class="exercise-row"><button class="check-btn" data-action="workout-toggle" data-id="${e(w.group+'-'+x.id)}" aria-pressed="${done}" aria-label="ทำแล้ว ${e(x.name)}">${icon('check')}</button><div class="row-text"><h3 class="row-title ${done?'done-text':''}">${e(x.name)}</h3><p class="row-note">${e(x.note)}</p></div><span class="sets">${n(x.sets)} เซต · ${e(x.reps)}</span><button class="icon-btn" data-action="exercise-edit" data-id="${e(x.id)}" aria-label="แก้ไข ${e(x.name)}">${icon('edit')}</button></div>`;}).join('')}</section>`:empty('ยังไม่มีรายการในกลุ่มนี้','เพิ่มท่าหรือกิจกรรมที่ต้องการ','exercise-add','เพิ่มรายการ')}`;}
 function careRow(x,editable=true){const done=d().care.includes(x.id);return `<div class="care-row"><button class="check-btn" data-action="care-toggle" data-id="${e(x.id)}" aria-pressed="${done}" aria-label="ทำแล้ว ${e(x.title)}">${icon('check')}</button><div class="row-text"><h3 class="row-title ${done?'done-text':''}">${e(x.title)}</h3><p class="row-note">${e(x.note)}</p></div>${editable?`<button class="icon-btn" data-action="care-edit" data-id="${e(x.id)}" aria-label="แก้ไข ${e(x.title)}">${icon('edit')}</button>`:''}</div>`;}
 function carePage(){return `<section class="card pet-banner"><svg class="pet-art" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="56" r="42" fill="#ece7d6"/><ellipse cx="37" cy="30" rx="10" ry="27" transform="rotate(-10 37 30)" fill="#d8c2a5"/><ellipse cx="64" cy="29" rx="10" ry="27" transform="rotate(10 64 29)" fill="#d8c2a5"/><ellipse cx="37" cy="29" rx="4" ry="19" fill="#ebd3c1"/><ellipse cx="64" cy="28" rx="4" ry="19" fill="#ebd3c1"/><ellipse cx="50" cy="65" rx="33" ry="28" fill="#f9f3e6"/><circle cx="39" cy="61" r="3" fill="#4b4940"/><circle cx="63" cy="61" r="3" fill="#4b4940"/><path d="m47 72 4 3 4-3" fill="#c6a38e"/></svg><div><p class="eyebrow">A LITTLE HOME FOR BOTH OF YOU</p><h2>คุณ & เจ้ากระแต</h2><p>กระต่ายลูกผสม Lionhead · อยู่ในคอก<br>เช็กลิสต์บันทึกสิ่งที่ดูแลจริงในวันที่เลือก</p></div></section>${notice('กันแดดสีเขียวเป็นเพียงแผนเปลี่ยน ยังไม่ยืนยันใช้จริง · เช็กลิสต์ไม่หมายความว่าทำแล้วจนกว่าคุณจะกดบันทึก · ผลิตภัณฑ์ใช้ตามฉลาก')}
  <div class="two-col">${[['self','ดูแลตัวเอง','care'],['pet','ดูแลกระแต','pet']].map(([category,title,i])=>`<section class="card"><div class="card-header"><h2>${icon(i)} ${title}</h2>${btn(icon('plus'),'care-add','soft',`data-category="${category}" aria-label="เพิ่ม${title}"`)}</div>${state.care.filter(x=>x.category===category).map(x=>careRow(x)).join('')||'<p class="small muted">ยังไม่มีรายการ เพิ่มได้ที่ปุ่ม +</p>'}</section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>บันทึกการดูแลวันนี้</h2><label for="careNote" class="small muted">บันทึกอัตโนมัติเมื่อพิมพ์ · เช่น อุณหภูมิที่วัดได้ หรือสิ่งที่อยากติดตาม</label><textarea id="careNote" class="care-note" maxlength="2000" placeholder="บันทึกของคุณ…">${e(d().careNote)}</textarea>${btn('บันทึกข้อความ','care-note','primary')}</section>`;}
 function settingsPage(){return `<div class="settings-grid"><section class="card"><h2>ค่าพื้นฐาน</h2><form id="settingsForm"><label class="field"><span>ชื่อที่ใช้ทักทาย</span><input name="name" maxlength="80" required value="${e(state.settings.name)}"></label><label class="field"><span>ค่าอ้างอิงน้ำ (มล.)</span><input name="waterReference" type="number" min="0" max="20000" step="50" required value="${state.settings.waterReference}"><small>เริ่มต้น 3,300 มล. · ใส่ 0 เพื่อปิด · เป็นเพียงค่าอ้างอิง ไม่ใช่เป้าหมายบังคับ</small></label><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></form><div class="setting-row"><h3>ข้อมูลเริ่มต้นจากบทสนทนา</h3><p>อยู่ที่วันที่ 19 ตุลาคม 2026 เท่านั้น วันที่อื่นสร้างตารางและอาหารอิสระ</p>${btn('ไปวันที่ 19 ต.ค. 2026','seed-date')}</div><div class="setting-row"><h3>แผนน้ำเริ่มต้น</h3><p>${state.water.length} รายการ รวม ${litres(state.water.reduce((a,x)=>a+x.ml,0))} ลิตร · ใช้กับวันที่ยังไม่เคยเปิดเท่านั้น การแก้น้ำแต่ละวันไม่กระทบวันเก่า</p></div></section>
  <section class="card"><h2>ข้อมูลของคุณ</h2><div class="setting-row"><h3>บันทึกเฉพาะอุปกรณ์นี้</h3><p>ข้อมูลอยู่ใน localStorage ของเบราว์เซอร์และที่อยู่เว็บนี้ ไม่มีบัญชีหรือการซิงก์ข้ามเครื่อง เปลี่ยนเบราว์เซอร์/โดเมน หรือใช้โหมดส่วนตัวอาจไม่เห็นข้อมูลเดิม การล้างข้อมูลเว็บไซต์จะลบข้อมูลที่บันทึกไว้</p></div><div class="setting-row"><h3>สำรองและย้ายข้อมูล</h3><p>ส่งออกไฟล์ JSON แล้วนำเข้าในอีกอุปกรณ์ การนำเข้าจะแทนที่ข้อมูลทั้งหมดในเบราว์เซอร์นี้ ควรส่งออกสำรองก่อน</p><div class="actions">${btn(icon('download')+' ส่งออก JSON','export','primary')}${btn('ดาวน์โหลดข้อมูลเดิมที่อ่านไม่ได้','raw-export','soft',storageBlocked&&rawBackup!==null?'':'hidden')}</div></div><div class="setting-row import-area"><label for="importFile"><strong>นำเข้าจากไฟล์ JSON</strong></label><input id="importFile" type="file" accept=".json,application/json"><p>ตรวจรูปแบบก่อนแสดงสรุปให้ยืนยัน ขนาดไม่เกิน 5 MB</p></div><div class="setting-row"><h3>เริ่มข้อมูลใหม่</h3><p>ล้างข้อมูลของแอปนี้แล้วคืนชุดเริ่มต้น จะมีหน้าต่างยืนยันก่อนล้าง</p>${btn('คืนข้อมูลเริ่มต้น','reset','danger')}</div></section></div>`;}
 function render(){
  $('#selectedDate').value=date;$('#pageTitle').textContent=routes[page][1];$('#pageSubtitle').textContent=routes[page][2];$('#breadcrumb').textContent=routes[page][0];$('#eyebrow').textContent=page==='dashboard'?'YOUR EVERYDAY, A LITTLE BETTER':'YOUR DAY / '+page.toUpperCase();
  $('#navigation').innerHTML=Object.keys(routes).filter(k=>k!=='settings').map(k=>`<button class="nav-item ${k===page?'active':''}" data-page="${k}" ${k===page?'aria-current="page"':''}>${icon(k)}${routes[k][0]}</button>`).join('');
  $('#settingsNav').innerHTML=icon('settings')+'ตั้งค่า';$('#settingsNav').classList.toggle('active',page==='settings');$('#settingsNav').setAttribute('aria-current',page==='settings'?'page':'false');
  const html={dashboard,water:waterPage,schedule:schedulePage,workout:workoutPage,meals:mealsPage,care:carePage,settings:settingsPage}[page]();
  $('#content').innerHTML=(storageBlocked?`<div class="storage-banner">${notice(e(storageIssue)+' <button class="text-btn" data-page="settings">จัดการ / สำรองข้อมูล</button>','error')}</div>`:'')+html+historySection();
  if(storageBlocked)$('#saveState').textContent='ยังไม่ได้บันทึกถาวร';
 }
 function historySection(){
  if(page==='care'){
   const records=d().careArchive||[];
   return records.length?`<section class="card" style="margin-top:24px"><div class="card-header"><div><h2>ประวัติรายการ</h2><p>รายการที่นำออกจากแผนแล้ว · เก็บบันทึกของวันที่เลือกไว้</p></div></div>${records.map(x=>careRow(x,false)).join('')}</section>`:'';
  }
  if(page==='workout'){
   const records=d().workoutArchive||[];
   return records.length?`<section class="card" style="margin-top:24px"><div class="card-header"><div><h2>ประวัติรายการ</h2><p>ท่าที่นำออกจากแผนแล้ว · เก็บบันทึกของวันที่เลือกไว้</p></div></div>${records.map(x=>`<div class="exercise-row"><button class="check-btn" data-action="workout-toggle" data-id="${e(x.id)}" aria-pressed="${d().workoutDone.includes(x.id)}" aria-label="ทำแล้ว ${e(x.name)}">${icon('check')}</button><div class="row-text"><h3 class="row-title">${e(x.name)}</h3><p class="row-note">กลุ่ม ${e(x.group)} · ${n(x.sets)} เซต · ${e(x.reps)} · ${e(x.note)}</p></div><span class="badge muted">นำออกจากแผนแล้ว</span></div>`).join('')}</section>`:'';
  }
  return '';
 }
 function navigate(p){if(!Object.hasOwn(routes,p))return;page=p;location.hash=p;closeNav();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
 function selectDate(value){if(!C.validDate(value)||value<'2000-01-01'||value>'2100-12-31'){toast('เลือกวันที่ระหว่างปี 2000–2100');return;}date=value;render();}
 function closeNav(){document.body.classList.remove('nav-open');$('#scrim').hidden=true;const closed=matchMedia('(max-width:900px)').matches||document.body.classList.contains('nav-collapsed');$('#menuButton').setAttribute('aria-expanded',String(!closed));$('#sidebar').inert=closed;}
 function toggleNav(){if(matchMedia('(max-width:900px)').matches){const open=!document.body.classList.contains('nav-open');document.body.classList.toggle('nav-open',open);$('#scrim').hidden=!open;$('#sidebar').inert=!open;$('#menuButton').setAttribute('aria-expanded',String(open));if(open)$('#closeNav').focus();else $('#menuButton').focus();}else{document.body.classList.toggle('nav-collapsed');const open=!document.body.classList.contains('nav-collapsed');$('#menuButton').setAttribute('aria-expanded',String(open));$('#sidebar').inert=!open;}}
 const toggle=(a,id)=>a.includes(id)?a.filter(x=>x!==id):[...a,id];
 function download(raw,name){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function statusOptions(value){return Object.entries(C.statuses).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v}</option>`).join('');}
 function field(label,name,value='',type='text',extra='',hint=''){return `<label class="field"><span>${label}</span><input name="${e(name)}" type="${type}" value="${e(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;}
 function textField(label,name,value='',max=2000){return `<label class="field"><span>${label}</span><textarea name="${e(name)}" maxlength="${max}">${e(value)}</textarea></label>`;}
 function openEditor(type,id,category){
  deleteArmed=false;let x,fields='',title='',deletable=false;editor={type,id,category,date};
  if(type==='water'){x=d().waterPlan.find(x=>x.id===id)||{time:'12:00',ml:300};title=id?'แก้ไขแก้วน้ำ':'เพิ่มแก้วน้ำ';fields=field('เวลา','time',x.time,'time','required')+field('ปริมาณ (มล.)','ml',x.ml,'number','required min="1" max="10000" step="1"')+'<p class="small muted">แก้ไขเฉพาะวันที่ '+thaiDate(date)+'</p>';deletable=!!id;}
  if(type==='schedule'){x=d().schedule.find(x=>x.id===id)||{time:'',title:'',status:'pending',note:''};title=id?'แก้ไขกิจกรรม':'เพิ่มกิจกรรม';fields=field('ชื่อกิจกรรม','title',x.title,'text','required maxlength="200"')+field('เวลาเริ่ม (เว้นว่างได้)','time',x.time,'time')+`<label class="field"><span>สถานะ</span><select name="status">${statusOptions(x.status)}</select></label>`+textField('ช่วงเวลา / รายละเอียด / สิ่งที่ยังไม่ยืนยัน','note',x.note);deletable=!!id;}
  if(type==='meal'){x=d().meals.find(x=>x.id===id)||{name:'',meal:'',note:'',estimated:true};title=id?'แก้ไขอาหาร':'เพิ่มอาหาร';fields=field('ชื่ออาหาร / เครื่องดื่ม','name',x.name,'text','required maxlength="200"')+field('มื้อ เช่น เช้า กลางวัน เย็น ของว่าง','meal',x.meal,'text','required maxlength="100"')+'<div class="form-grid">'+[['kcal','พลังงาน (kcal)'],['protein','โปรตีน (กรัม)'],['carbs','คาร์บ (กรัม)'],['fat','ไขมัน (กรัม)'],['fiber','ใยอาหาร (กรัม)'],['sodium','โซเดียม (มก.)']].map(([k,l])=>field(l,k,x[k]??'','number','min="0" max="100000" step="0.1"')).join('')+'</div><p class="small muted">เว้นว่าง = ไม่ทราบ · ใส่ 0 เฉพาะเมื่อทราบว่าเป็นศูนย์</p>'+`<label class="check-field"><input type="checkbox" name="estimated" ${x.estimated?'checked':''}>เป็นค่าประมาณ</label>`+textField('แหล่งข้อมูล / หมายเหตุ / ช่วงประมาณ','note',x.note);deletable=!!id;}
  if(type==='exercise'){const w=C.workoutFor(state,date);editor.group=w.group;x=w.exercises.find(x=>x.id===id)||{name:'',sets:3,reps:'',note:''};title=id?'แก้ไขท่า / กิจกรรม':'เพิ่มท่า / กิจกรรม';fields=notice('ใช้กับกลุ่ม '+w.group+' ทุกสัปดาห์ การทำแล้วบันทึกแยกวัน')+field('ชื่อท่า / กิจกรรม','name',x.name,'text','required maxlength="200"')+field('จำนวนเซต','sets',x.sets,'number','required min="1" max="100" step="1"')+field('จำนวนครั้ง / ระยะเวลา / ตามความพร้อม','reps',x.reps,'text','maxlength="200"')+textField('หมายเหตุ','note',x.note);deletable=!!id;}
  if(type==='care'){x=state.care.find(x=>x.id===id)||{title:'',category:category||'self',note:''};title=id?'แก้ไขเช็กลิสต์':'เพิ่มเช็กลิสต์';fields=field('ชื่อรายการ','title',x.title,'text','required maxlength="200"')+`<label class="field"><span>หมวด</span><select name="category"><option value="self" ${x.category==='self'?'selected':''}>ดูแลตัวเอง</option><option value="pet" ${x.category==='pet'?'selected':''}>ดูแลกระแต</option></select></label>`+textField('รายละเอียด / สถานะที่ยังไม่ยืนยัน','note',x.note)+notice('แก้รายการมีผลทุกวัน การทำแล้วบันทึกแยกตามวัน');deletable=!!id;}
  if(type==='phase'){title='แก้ไขช่วงเวลาออกกำลังกาย';fields=state.phases.map(x=>field(e(x.name)+' (นาที)',x.id,x.minutes,'number','required min="0" max="500" step="1"')).join('')+notice('เปลี่ยนการแบ่งเวลาของแผนเวททุกวัน รวมเวลาอาจต่างจากช่วง 16:30–18:00');}
  if(type==='plan'){title='แผนประจำ'+['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์'][new Date(date+'T12:00:00').getDay()];fields=`<label class="field"><span>กลุ่มกิจกรรม</span><select name="group">${[['A','กลุ่ม A · อก ไหล่ หน้าท้อง'],['B','กลุ่ม B · หลัง แขน ขา'],['rest','พัก'],['active','Active recovery']].map(([k,v])=>`<option value="${k}" ${C.workoutFor(state,date).group===k?'selected':''}>${v}</option>`).join('')}</select></label>`+notice('มีผลกับวันเดียวกันของสัปดาห์ทั้งหมด บันทึกการทำแล้วเดิมยังอยู่');}
  if(type==='copy'){title='คัดลอกตารางจากวันที่อื่น';fields=field('วันที่ต้นทาง','source',date==='2026-10-19'?shift(date,-1):'2026-10-19','date','required min="2000-01-01" max="2100-12-31"')+notice('เพิ่มกิจกรรมจากต้นทางต่อท้ายตารางวันนี้ โดยเริ่มสถานะเป็น “ยังไม่ทำ” ทั้งหมด ไม่คัดลอกสถานะทำแล้ว');}
  if(type==='reset'){title='ยืนยันคืนข้อมูลเริ่มต้น';fields=notice('ข้อมูลปัจจุบันทั้งหมดในแอปนี้จะถูกแทนที่ รวมประวัติทุกวัน แนะนำให้ส่งออก JSON ก่อน','warning')+`<label class="check-field"><input name="confirm" type="checkbox" required>ฉันสำรองแล้ว / ต้องการเริ่มใหม่</label>`;}
  if(type==='import'){title='ตรวจแล้ว · พร้อมนำเข้า';fields=notice(`พบข้อมูล ${Object.keys(editorImport.days).length} วัน · แผนน้ำเริ่มต้น ${editorImport.water.length} รายการ<br>การนำเข้าจะแทนที่ข้อมูลทั้งหมดในเครื่องนี้`,'warning')+`<label class="check-field"><input name="confirm" type="checkbox" required>ยืนยันแทนที่ข้อมูลปัจจุบัน</label>`;}
  $('#editorTitle').textContent=title;$('#editorFields').innerHTML=fields;$('#formError').textContent='';$('#deleteItem').hidden=!deletable;$('#deleteItem').textContent='ลบรายการ';$('#editor').showModal();
 }
 let editorImport=null;
 function upsert(list,value){const at=list.findIndex(x=>x.id===value.id);if(at<0)list.push(value);else list[at]=value;}
 function closeEditor(){if($('#editor').open)$('#editor').close();editor=null;editorImport=null;}
 function submitEditor(ev){ev.preventDefault();if(!editor)return;const f=new FormData($('#editorForm')),v=k=>String(f.get(k)??'').trim(),number=k=>v(k)===''?null:Number(v(k)),type=editor.type,id=editor.id||C.uid(),previous=C.clone(state);
  try{
   for(const input of $('#editorForm').querySelectorAll('input[type="text"][required]'))if(!input.value.trim())throw Error('กรอกชื่อรายการก่อนบันทึก');
   if(type==='water'){upsert(d().waterPlan,{id,time:v('time'),ml:Number(v('ml'))});d().waterPlan.sort((a,b)=>a.time.localeCompare(b.time));}
   if(type==='schedule'){upsert(d().schedule,{id,time:v('time'),title:v('title'),status:v('status'),note:v('note')});d().schedule.sort((a,b)=>(a.time||'00:00').localeCompare(b.time||'00:00'));}
   if(type==='meal')upsert(d().meals,{id,name:v('name'),meal:v('meal'),kcal:number('kcal'),protein:number('protein'),carbs:number('carbs'),fat:number('fat'),fiber:number('fiber'),sodium:number('sodium'),estimated:f.has('estimated'),note:v('note')});
   if(type==='exercise')upsert(state.workouts[editor.group].exercises,{id,name:v('name'),sets:Number(v('sets')),reps:v('reps'),note:v('note')});
   if(type==='care')upsert(state.care,{id,title:v('title'),category:v('category'),note:v('note')});
   if(type==='phase')state.phases.forEach(x=>x.minutes=Number(v(x.id)));
   if(type==='plan')state.week[new Date(date+'T12:00:00').getDay()]=v('group');
   if(type==='copy'){if(v('source')===date)throw Error('เลือกวันที่อื่นเพื่อคัดลอก');const source=state.days[v('source')];if(!source?.schedule.length)throw Error('วันที่ต้นทางยังไม่มีตาราง');d().schedule.push(...source.schedule.map(x=>({...x,id:C.uid(),status:'pending'})));d().schedule.sort((a,b)=>(a.time||'00:00').localeCompare(b.time||'00:00'));}
   if(type==='reset'){state=C.createState();storageBlocked=false;storageIssue='';rawBackup=null;}
   if(type==='import'){state=C.clone(editorImport);storageBlocked=false;storageIssue='';rawBackup=null;}
   C.validate(state);save('บันทึกแล้ว');closeEditor();render();
  }catch(err){state=previous;$('#formError').textContent=err.message;}
 }
 function deleteCurrent(){if(!editor)return;if(!deleteArmed){deleteArmed=true;$('#deleteItem').textContent='กดอีกครั้งเพื่อยืนยันลบ';return;}const {type,id,group}=editor;
  if(type==='water'){d().waterPlan=d().waterPlan.filter(x=>x.id!==id);d().water=d().water.filter(x=>x!==id);}
  if(type==='schedule')d().schedule=d().schedule.filter(x=>x.id!==id);
  if(type==='meal')d().meals=d().meals.filter(x=>x.id!==id);
  if(type==='exercise'){const item=state.workouts[group].exercises.find(x=>x.id===id);for(const day of Object.values(state.days))if(day.workoutDone.includes(group+'-'+id)){day.workoutArchive??=[];upsert(day.workoutArchive,{...C.clone(item),id:group+'-'+id,group});}state.workouts[group].exercises=state.workouts[group].exercises.filter(x=>x.id!==id);}
  if(type==='care'){const item=state.care.find(x=>x.id===id);for(const day of Object.values(state.days))if(day.care.includes(id)){day.careArchive??=[];upsert(day.careArchive,C.clone(item));}state.care=state.care.filter(x=>x.id!==id);}
  save('ลบรายการแล้ว');closeEditor();render();
 }
 document.addEventListener('click',ev=>{
  const p=ev.target.closest('[data-page]');if(p){navigate(p.dataset.page);return;}
  if(ev.target.closest('[data-close]')){closeEditor();return;}
  const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  const focusKey={action:a,id};let changed=false;
  if(a==='water-toggle'){d().water=toggle(d().water,id);changed=true;}
  if(a==='care-toggle'){d().care=toggle(d().care,id);changed=true;}
  if(a==='workout-toggle'){d().workoutDone=toggle(d().workoutDone,id);changed=true;}
  for(const [prefix,type] of [['water','water'],['schedule','schedule'],['meal','meal'],['exercise','exercise'],['care','care']])if(a===prefix+'-add'||a===prefix+'-edit'){openEditor(type,id,b.dataset.category);return;}
  if(a==='phase-edit')openEditor('phase');if(a==='workout-plan')openEditor('plan');if(a==='schedule-copy')openEditor('copy');if(a==='reset')openEditor('reset');
  if(a==='select-date')selectDate(b.dataset.date);if(a==='seed-date'){date='2026-10-19';navigate('dashboard');}
  if(a==='water-default'){state.water=C.clone(d().waterPlan);save('ใช้แผนนี้กับวันที่ยังไม่เคยเปิดแล้ว');}
  if(a==='care-note'){d().careNote=$('#careNote').value;save('บันทึกข้อความแล้ว');}
  if(a==='export')download(JSON.stringify(state,null,2),'jai-daily-'+localDate()+'.json');
  if(a==='raw-export')download(rawBackup,'jai-daily-original-backup.json');
  if(a==='reload-data'){try{state=C.parseImport(localStorage.getItem(KEY));storageBlocked=false;render();}catch{toast('ยังอ่านข้อมูลใหม่ไม่ได้');}}
  if(changed){save();render();toast(storageBlocked?'ยังบันทึกในเครื่องไม่ได้ · ส่งออก JSON เพื่อสำรอง':a==='water-toggle'?`บันทึกน้ำ ${litres(stats().ml)} ลิตร · ${stats().count} แก้ว`:'บันทึกสถานะแล้ว');const target=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===focusKey.action&&x.dataset.id===focusKey.id);target?.focus({preventScroll:true});}
 });
 document.addEventListener('input',ev=>{if(ev.target.id==='careNote'){d().careNote=ev.target.value;save();}});
 document.addEventListener('change',async ev=>{
  if(ev.target.matches('[data-status-id]')){const id=ev.target.dataset.statusId;d().schedule.find(x=>x.id===id).status=ev.target.value;save('บันทึกสถานะแล้ว');render();[...document.querySelectorAll('[data-status-id]')].find(x=>x.dataset.statusId===id)?.focus({preventScroll:true});}
  if(ev.target.id==='importFile'){
   try{const file=ev.target.files[0];if(!file)return;if(file.size>5000000)throw Error('ไฟล์ใหญ่เกิน 5 MB');editorImport=C.parseImport(await file.text());openEditor('import');}catch(err){toast('นำเข้าไม่ได้: '+err.message);}finally{ev.target.value='';}
  }
 });
 document.addEventListener('submit',ev=>{if(ev.target.id!=='settingsForm')return;ev.preventDefault();const f=new FormData(ev.target);state.settings.name=String(f.get('name')).trim()||'คุณ';state.settings.waterReference=Number(f.get('waterReference'));save('บันทึกการตั้งค่าแล้ว');render();});
 $('#editorForm').addEventListener('submit',submitEditor);$('#deleteItem').addEventListener('click',deleteCurrent);$('#editor').addEventListener('cancel',()=>{editor=null;editorImport=null;});
 $('#menuButton').innerHTML=icon('menu');$('#menuButton').addEventListener('click',toggleNav);$('#closeNav').addEventListener('click',()=>{closeNav();$('#menuButton').focus();});$('#scrim').addEventListener('click',closeNav);
 $('#selectedDate').addEventListener('change',ev=>selectDate(ev.target.value));$('#prevDate').addEventListener('click',()=>selectDate(shift(date,-1)));$('#nextDate').addEventListener('click',()=>selectDate(shift(date,1)));$('#today').addEventListener('click',()=>selectDate(localDate()));
 window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(Object.hasOwn(routes,next)&&next!==page){page=next;render();closeNav();}});
 const mq=matchMedia('(max-width:900px)');mq.addEventListener('change',()=>{document.body.classList.remove('nav-collapsed');closeNav();$('#sidebar').inert=mq.matches;$('#menuButton').setAttribute('aria-expanded',String(!mq.matches));});
 document.addEventListener('keydown',ev=>{if(!document.body.classList.contains('nav-open'))return;if(ev.key==='Escape'){closeNav();$('#menuButton').focus();}if(ev.key==='Tab'){const items=[...$('#sidebar').querySelectorAll('button')].filter(x=>x.getClientRects().length);if(ev.shiftKey&&document.activeElement===items[0]){ev.preventDefault();items.at(-1).focus();}else if(!ev.shiftKey&&document.activeElement===items.at(-1)){ev.preventDefault();items[0].focus();}}});
 window.addEventListener('storage',ev=>{if(ev.key===KEY){storageBlocked=true;storageIssue='ข้อมูลถูกเปลี่ยนจากอีกแท็บ กรุณาส่งออกงานในแท็บนี้ก่อน แล้วรีเฟรชหน้าเพื่อใช้ข้อมูลล่าสุด';render();}});
 closeNav();$('#sidebar').inert=mq.matches;$('#menuButton').setAttribute('aria-expanded',String(!mq.matches));render();
})();
